  window.renderUniformIcon = function (name, size, color, stroke) {
    const s = size || 20;
    const c = color || 'currentColor';
    const sw = stroke || 2;
    const tpl = window.ANNASUTRA_ICONS[name] || window.ANNASUTRA_ICONS['box'] || '';
    return tpl.replace(/{size}/g, s).replace(/{color}/g, c).replace(/{stroke}/g, sw);
  };

  window.updateCountryFlag = function (selectEl) {
    const sel = selectEl || document.getElementById('countryCodeSelect');
    const badge = document.getElementById('countryFlagBadge');
    if (!sel || !badge) return;
    const code = sel.value || '+91';
    badge.innerHTML = window.ANNASUTRA_COUNTRY_FLAGS[code] || window.ANNASUTRA_COUNTRY_FLAGS['+91'];
  };

  window.openHelpModal = function () {
    const modal = document.getElementById('helpModal');
    if (modal) modal.style.display = 'flex';
  };

  window.closeHelpModal = function () {
    const modal = document.getElementById('helpModal');
    if (modal) modal.style.display = 'none';
  };

