// Apply complete localization across all pages (landing, lot_summary, lot_not_found, modals)
window.applyAnnaSutraI18n = function(lang) {
  if (!window.EXTRA_I18N) return;
  const dict = window.EXTRA_I18N[lang] || window.EXTRA_I18N['en'] || {};
  const enDict = window.EXTRA_I18N['en'] || {};

  // Merge into page I18N if present so existing setLanguage() sees all 11 languages
  if (typeof I18N !== 'undefined') {
    Object.keys(window.EXTRA_I18N).forEach(function(k) {
      I18N[k] = Object.assign({}, I18N['en'] || {}, I18N[k] || {}, window.EXTRA_I18N[k]);
    });
  }

  // Apply every key that maps to a DOM element ID
  const placeholderIds = {
    'navLotPlaceholder': 'navLotInput',
    'phonePlaceholder': 'phoneInput'
  };

  Object.keys(enDict).forEach(function(key) {
    const val = dict[key] !== undefined ? dict[key] : enDict[key];
    if (!val) return;
    if (placeholderIds[key]) {
      const inp = document.getElementById(placeholderIds[key]);
      if (inp) inp.placeholder = val;
      return;
    }
    const el = document.getElementById(key);
    if (el) {
      el.textContent = val;
    }
  });

  // Also translate lot_summary stage pills if present
  const stageMap = {
    'Harvested': dict.flowStep1Title || 'Harvested',
    'Aggregated': dict.flowStep2Title || 'Aggregated',
    'Wholesaled': dict.flowStep3Title || 'Wholesaled',
    'Distributed': dict.flowStep4Title || 'Distributed',
    'Retailed': dict.flowStep5Title || 'Retailed'
  };
  document.querySelectorAll('.stage-pill').forEach(function(pill) {
    const raw = pill.getAttribute('data-raw-stage') || pill.textContent.trim();
    pill.setAttribute('data-raw-stage', raw);
    for (const k in stageMap) {
      if (raw.indexOf(k) !== -1) {
        pill.textContent = '' + stageMap[k];
        break;
      }
    }
  });
};